-- POST-SEED CHECKS: if any returns rows, investigate; do NOT disable FK/check constraints.
SELECT 'employees' table_name, COUNT(*) cnt FROM dbo.employees
UNION ALL SELECT 'accounts',COUNT(*) FROM dbo.accounts
UNION ALL SELECT 'work_schedules',COUNT(*) FROM dbo.work_schedules
UNION ALL SELECT 'attendance_records',COUNT(*) FROM dbo.attendance_records
UNION ALL SELECT 'employee_requests',COUNT(*) FROM dbo.employee_requests
UNION ALL SELECT 'overtime_requests',COUNT(*) FROM dbo.overtime_requests
UNION ALL SELECT 'payroll_batches',COUNT(*) FROM dbo.payroll_batches
UNION ALL SELECT 'payroll_details',COUNT(*) FROM dbo.payroll_details
UNION ALL SELECT 'payroll_lines',COUNT(*) FROM dbo.payroll_lines;
SELECT f.name AS fk_name, OBJECT_NAME(f.parent_object_id) AS child_table, f.is_disabled, f.is_not_trusted
FROM sys.foreign_keys f WHERE f.is_disabled=1 OR f.is_not_trusted=1;
-- Avoid DBCC CHECKCONSTRAINTS across all constraints here: SQL Server may raise Msg 446
-- for the mixed explicit/default collations in the original accounts schema.
-- These checks do not modify data or disable constraints.
IF EXISTS (SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1)
    THROW 52090, N'Có khóa ngoại bị tắt hoặc chưa trusted. Kiểm tra lại schema.', 1;
IF EXISTS (SELECT 1 FROM sys.check_constraints WHERE is_disabled=1 OR is_not_trusted=1)
    THROW 52091, N'Có CHECK constraint bị tắt hoặc chưa trusted. Kiểm tra lại schema.', 1;
-- Direct FK orphan checks for high-use HRM relationships.
IF EXISTS (SELECT 1 FROM dbo.accounts a LEFT JOIN dbo.employees e ON e.employee_id=a.employee_id WHERE e.employee_id IS NULL)
    THROW 52092, N'accounts có employee_id không hợp lệ.', 1;
IF EXISTS (SELECT 1 FROM dbo.employee_assignments a LEFT JOIN dbo.employees e ON e.employee_id=a.employee_id WHERE e.employee_id IS NULL)
    THROW 52093, N'employee_assignments có employee_id không hợp lệ.', 1;
IF EXISTS (SELECT 1 FROM dbo.attendance_records ar LEFT JOIN dbo.employees e ON e.employee_id=ar.employee_id WHERE e.employee_id IS NULL)
    THROW 52094, N'attendance_records có employee_id không hợp lệ.', 1;
IF EXISTS (SELECT 1 FROM dbo.payroll_details d LEFT JOIN dbo.payroll_batches b ON b.batch_id=d.batch_id WHERE b.batch_id IS NULL)
    THROW 52095, N'payroll_details có batch_id không hợp lệ.', 1;
PRINT N'Đã kiểm tra FK/CHECK được bật và trusted, cùng các liên kết dữ liệu chính.';
PRINT N'Ghi chú: Đây không thay thế DBCC CHECKCONSTRAINTS toàn bộ. Chạy kiểm tra từng constraint khi cần.';
GO

-- Nhân viên dành riêng cho API test; sau Postman nếu có hợp đồng thì dùng DB test mới để chạy lại.
SELECT e.employee_id,e.employee_code,e.full_name,
       (SELECT COUNT(*) FROM dbo.contracts c WHERE c.employee_id=e.employee_id) AS so_hop_dong
FROM dbo.employees e WHERE e.employee_code IN ('EMP026','EMP027','EMP028','EMP029')
ORDER BY e.employee_code;
